class Solution:
    def numDecodings(self, s: str) -> int:
        if not s or s[0] == '0':
            return 0
        two_back, one_back = 1, 1  # ways to decode s[:i-1] and s[:i]
        for i in range(1, len(s)):
            cur = 0
            if s[i] != '0':
                cur += one_back  # s[i] stands alone
            if s[i - 1] == '1' or (s[i - 1] == '2' and s[i] <= '6'):
                cur += two_back  # s[i-1:i+1] is one letter 10..26
            two_back, one_back = one_back, cur
        return one_back

